const teamBackendConfig={url:'https://gaalukxbmzvtjwsfyssw.supabase.co',publishableKey:'sb_publishable_Eh1tZAXIIAkJe2QgUZsAWQ_F18R_Cp4'};
let teamPasswordSetup=['invite','recovery'].includes(new URLSearchParams(location.hash.slice(1)).get('type'));
let teamClient=null,teamUser=null,teamRole=null,teamLoading=false,teamSaving=false;
let reviewWorkflow={},workflowVersions={};
let teamStatus='Fælles lagring afventer tilslutning.';
const workflowState=key=>reviewWorkflow[key]||{};
function teamCanEdit(){return !!teamUser&&!!teamRole&&!teamLoading&&!teamSaving;}
async function persistWorkflow(key,field,value){
 if(!teamCanEdit()){teamStatus='Log ind som medarbejder for at ændre status.';renderTeamLogin();return false;}
 teamSaving=true;teamStatus='Gemmer fælles status…';renderTeamLogin();
 try{
  const {data,error}=await teamClient.rpc('klippen_update_workflow',{p_key:key,p_field:field,p_value:value,p_version:workflowVersions[key]||0});
  if(error)throw error;
  const row=Array.isArray(data)?data[0]:data;if(!row?.key)throw Error('Serveren har ikke bekræftet ændringen.');
  reviewWorkflow[row.key]={...row.state,updatedAt:row.updated_at,updatedBy:row.updated_by};workflowVersions[row.key]=row.version;
  teamStatus='Gemt fælles · '+new Date(row.updated_at).toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'});return true;
 }catch(error){teamStatus='Ikke gemt: '+(error.message||'Forbindelsen svigtede.');return false;}
 finally{teamSaving=false;renderTeamLogin();}
}
function workflowCheck(key,field,label){const e=escapeHTML;return `<label class="workflow-check"><input type="checkbox" data-workflow-key="${e(key)}" data-field="${field}" ${workflowState(key)[field]?'checked':''} ${!teamCanEdit()||(['notReal','strategy'].includes(field)&&teamRole!=='manager')?'disabled':''}>${e(label)}</label>`;}
function renderAspectCards(aspects){
 const e=escapeHTML;const groups=new Map();for(const a of aspects){const key=a.r.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(a);}
 const cards=[...groups.values()];return '<div class="aspect-list">'+cards.map((group,index)=>{const r=group[0].r;const key=r.id;const bad=group[0].sentiment==='bad';return `<article class="aspect-card" ${index>=3?'hidden':''}><div class="eyebrow">${e(properties.find(p=>p.id===r.property).name)} · ${e(group[0].room)}</div><h4>${e(r.author)} · ${e(r.platform)}</h4><div class="meta">${e(r.publishedDate||r.publishedMonth||(r.publishedRelative+' (vist '+r.observedAt.slice(0,10)+')'))}</div>${group.map(a=>{const issue=key+'|'+a.category;return `<div class="aspect-detail"><strong>${e(reviewCategories[a.category])}</strong><p>${e(a.detail)}</p>${bad?`${workflowCheck(issue,'fixed','Fejlen er udbedret')}${workflowCheck(issue,'notReal','Ikke en konstateret fejl')}<label class="workflow-note">${workflowState(issue).notReal?'Begrundelse og lederens vurdering (påkrævet)':'Notat om udbedring / undersøgelse'}<textarea data-workflow-key="${e(issue)}" data-field="issueNote" ${!teamCanEdit()?'disabled':''} placeholder="Hvad er undersøgt eller ændret?">${e(workflowState(issue).issueNote||'')}</textarea></label>`:''}</div>`;}).join('')}<details class="suggestion"><summary>Forslag til svar</summary><p>${e(suggestedReply(r))}</p><small>Tilpas udkastet og kontrollér den originale anmeldelse før afsendelse.</small></details>${bad?`<p class="meta">${workflowState(key).updatedBy?'Senest ændret af '+e(workflowState(key).updatedBy):'Ingen fælles status registreret'}</p>${workflowCheck(key,'contacted','Kunden er kontaktet (telefon eller skriftligt)')}<label class="workflow-note">Kontakt / ansvarlig / dato<textarea data-workflow-key="${e(key)}" data-field="contactNote" ${!teamCanEdit()?'disabled':''} placeholder="Fx Maiken · telefon · 8. oktober">${e(workflowState(key).contactNote||'')}</textarea></label>`:''}<a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">Åbn anmeldelsen</a></article>`;}).join('')+(cards.length>3?`<button type="button" data-show-more>Vis alle ${cards.length} anmeldelser</button>`:'')+(cards.length?'':'<p class="empty-text">Ingen åbne punkter for dette valg.</p>')+'</div>';
}
function bindWorkflowControls(host){
 host.querySelectorAll('[data-workflow-key]').forEach(input=>input.addEventListener('change',async ()=>{
  const key=input.dataset.workflowKey,field=input.dataset.field,value=input.type==='checkbox'?input.checked:input.value;
  if(field==='notReal'&&value&&!workflowState(key).issueNote?.trim()){alert('Skriv først en begrundelse og lederens vurdering.');input.checked=false;return;}
  if(field==='answered'&&value&&reviewNeedsApproval(nightReport.reviews.find(r=>r.id===key)||{})&&!workflowState(key).strategy){alert('Aftal først svarstrategien med en leder.');input.checked=false;return;}
  if(field==='strategy'&&value&&!workflowState(key).strategyNote?.trim()){alert('Skriv først den aftalte strategi og hvilken leder, den er aftalt med.');input.checked=false;return;}
  input.disabled=true;const saved=await persistWorkflow(key,field,value);if(!saved&&input.type==='checkbox')input.checked=!value;renderReviewTopics();renderNightReport();renderTodayOverview();renderPrivateFeedback();
 }));
}
let showHandledReplies=false,replyFilter='all';
function reviewNeedsApproval(r){return !Number.isFinite(r.score)||!Number.isFinite(r.scale)||r.scale<=0||r.score/r.scale<0.8;}
function suggestedReply(r){
 const evidence=reviewAspectEvidence.find(a=>a.reviewId===r.id)?.aspects||[];
 const clean=s=>String(s).trim().replace(/[.;]+$/, '');
 const praise=[...new Set(evidence.filter(a=>a.sentiment==='good').map(a=>clean(a.detail)))];
 const issues=[...new Set(evidence.filter(a=>a.sentiment==='bad').map(a=>clean(a.detail)))];
 const hash=Array.from(String(r.id||r.author||'')).reduce((n,c)=>(Math.imul(n,31)+c.charCodeAt(0))>>>0,7);
 const pick=(options,salt)=>options[((hash>>>salt)+salt)%options.length];
 const name=r.author||'gæst';
 const place=properties.find(p=>p.id===r.property)?.name||'os';
 const opening=pick([`Hej ${name}.`,`Kære ${name}.`,`Hej ${name},`],0);
 const thanks=pick(['Tak, fordi du tog dig tid til at fortælle om din oplevelse.','Mange tak for din anmeldelse og din feedback.','Tak for at dele dine indtryk med os.','Tak, fordi du har skrevet om dit besøg.','Vi sætter pris på, at du fortæller os om din oplevelse.','Tak for din tilbagemelding.'],3);
 const praiseText=praise.length?pick([`Vi blev især glade for din ros: ${praise.join('; ')}.`,`Det glæder os at læse det, du fremhæver: ${praise.join('; ')}.`,`Tak for de gode ord om oplevelsen hos ${place}: ${praise.join('; ')}.`,`De positive ting, du nævner, betyder meget for os: ${praise.join('; ')}.`],6):'';
 const signoff=pick([`Venlig hilsen teamet på ${place}`,`De bedste hilsner fra ${place}`,`Mange hilsner fra os på ${place}`],11);
 if(issues.length||reviewNeedsApproval(r)){
  const acknowledgement=pick(['Vi er kede af, at der var dele af oplevelsen, som ikke levede op til dine forventninger.','Det er ærgerligt at læse, at besøget ikke blev helt, som du havde håbet.','Tak for at gøre os opmærksomme på det, der ikke fungerede for dig.','Vi beklager, at din oplevelse gav anledning til utilfredshed.'],8);
  const issueText=issues.length?pick([`Du beskriver blandt andet: ${issues.join('; ')}.`,`Vi har læst dine bemærkninger om: ${issues.join('; ')}.`,`Det, du især peger på, er: ${issues.join('; ')}.`],13):'';
  const followup=pick(['Du er velkommen til at kontakte os direkte, så vi kan høre mere om dit besøg.','Hvis du har lyst, må du gerne skrive til os direkte og uddybe din oplevelse.','Vi vil gerne høre nærmere fra dig; du er meget velkommen til at tage direkte kontakt.'],16);
  return [opening,thanks,praiseText,acknowledgement,issueText,followup,signoff].filter(Boolean).join(' ');
 }
 const closing=pick(['Vi håber at se dig igen en anden gang.','Det ville være dejligt at byde dig velkommen igen.','Tak for besøget – du er altid velkommen tilbage.','Vi håber, at vejen fører dig forbi os igen.','Tak for de fine ord og for besøget hos os.'],19);
 return [opening,thanks,praiseText,closing,signoff].filter(Boolean).join(' ');
}

function renderNightReport(){
 const h=document.querySelector('#nightReport');if(!h)return;const e=escapeHTML;
 const matches=r=>(selected==='all'||r.property===selected)&&(platform==='all'||r.platform===platform);
 const all=nightReport.reviews.filter(matches);
 const waiting=all.filter(r=>r.replyStatus==='unanswered'&&(showHandledReplies||!workflowState(r.id).answered)&&(replyFilter==='all'||(replyFilter==='approval'?reviewNeedsApproval(r)&&!workflowState(r.id).strategy:!reviewNeedsApproval(r)||workflowState(r.id).strategy)));
 const unknown=all.filter(r=>r.replyStatus==='unknown');
 renderTodayOverview();
 const criticism=r=>reviewAspectEvidence.find(a=>a.reviewId===r.id)?.aspects.some(a=>a.sentiment==='bad')||r.priority;
 const pending=all.filter(r=>r.replyStatus==='unanswered'&&!workflowState(r.id).answered).length;
 h.innerHTML=`<div class="section-heading"><div><div class="eyebrow">SVAR TIL GÆSTERNE</div><h2>Mangler svar</h2></div><span class="tag">${pending} i det kontrollerede udsnit</span></div><p class="section-intro">Både ros og ris skal have et svar. Her vises anmeldelser uden synligt ejersvar ved seneste kontrol. Listen er et udsnit, ikke en komplet svarrestanceliste. Kundekontakt og udbedring ovenfor erstatter ikke et offentligt svar.</p><p class="workflow-storage">Status og noter er kun synlige for godkendte medarbejdere. “Svar sendt” er jeres egen markering; platformens svarstatus ændres først ved en ny kontrol.</p><label class="select-label">Vis svar<select id="replyFilter"><option value="all">Alle</option><option value="ready" ${replyFilter==='ready'?'selected':''}>Kan besvares</option><option value="approval" ${replyFilter==='approval'?'selected':''}>Afventer ledergodkendelse</option></select></label><label class="workflow-check"><input id="showHandledReplies" type="checkbox" ${showHandledReplies?'checked':''}>Vis også dem, vi selv har markeret som besvaret</label><div class="reply-grid">${waiting.map(r=>{const bad=reviewNeedsApproval(r);return `<article class="aspect-card"><span class="type ${bad?'improve':''}">${bad?(workflowState(r.id).strategy?'GODKENDT · KAN BESVARES':'AFVENTER LEDERGODKENDELSE'):'KAN BESVARES'}</span><h3>${e(r.author)} · ${e(properties.find(p=>p.id===r.property).name)}</h3><div class="meta">${e(r.platform)} · ${e(r.publishedDate||r.publishedMonth||r.publishedRelative)}</div><p>${e(r.summary)}</p>${bad?`<div class="suggestion"><strong>Aftal svarstrategi med lederen</strong><p>Undersøg hændelsen og dokumentationen. Aftal kundekontakt og et roligt svar. Hvis anmeldelsen muligvis bryder platformens regler, skal lederen vurdere en anmeldelse til platformen. Kritik alene er ikke grundlag for fjernelse.</p></div><label class="workflow-note">Svarstrategi og leder<textarea data-workflow-key="${e(r.id)}" data-field="strategyNote" ${!teamCanEdit()?'disabled':''} placeholder="Hvad svarer vi, hvem godkender, og skal platformens regler undersøges?">${e(workflowState(r.id).strategyNote||'')}</textarea></label>${workflowCheck(r.id,'strategy','Svarstrategi godkendt af Jannie, Thomas eller Martin')}`:'<p>Tilpas svaret til både rosen og eventuelle problemer i anmeldelsen.</p>'}<details class="suggestion" open><summary>Forslag til svar – tilpas før afsendelse</summary><p>${e(suggestedReply(r))}</p><small>Udkast ud fra det kontrollerede referat. Kontrollér den originale anmeldelse. Lov kun tiltag, som faktisk er aftalt.</small></details>${workflowCheck(r.id,'answered','Offentligt svar er sendt på platformen')}<a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">${bad&&!workflowState(r.id).strategy?'Se anmeldelsen · svar afventer godkendelse':'Åbn anmeldelsen og svar på platformen'}</a></article>`;}).join('')||'<p>Ingen anmeldelser mangler svar i dette kontrollerede udsnit.</p>'}</div>${unknown.length?`<details><summary>Svarstatus skal kontrolleres (${unknown.length})</summary>${unknown.map(r=>`<p><a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">${e(r.author)} · ${e(r.platform)}</a> — svarstatus ukendt.</p>`).join('')}</details>`:''}<details class="coverage-details"><summary>Seneste kontrol og dækning</summary>${nightReport.coverage.filter(c=>platform==='all'||c.platform===platform).map(c=>`<p><strong>${e(c.platform)} · ${e(c.status)}</strong><br>${e(c.detail)}</p>`).join('')}<p>Senest kontrolleret: ${e(nightReport.observedAt.slice(0,10))}. Ingen svar sendes automatisk.</p></details>`;
 h.querySelector('#replyFilter').addEventListener('change',ev=>{replyFilter=ev.target.value;renderNightReport();});
 h.querySelector('#showHandledReplies').addEventListener('change',ev=>{showHandledReplies=ev.target.checked;renderNightReport();});bindWorkflowControls(h);
}
function partyIllustration(){return `<img class="party-pind" src="assets/pind-fejrer.png" width="240" height="250" alt="Pind, tegnet efter Jannies pindsvin, med festhat og Bornholms flag. Håndskrevet navn og pil.">`;}
let partyPlayed=false,partyContext=null,partyAttempting=false;
async function playPartySound(){
 if(partyAttempting)return;const box=document.querySelector('#celebration');if(!box||box.hidden||!box.dataset.newsId)return;
 const id=box.dataset.newsId;if(partyPlayed===id)return;try{if(localStorage.getItem('klippen-party-seen')===id)return;}catch{}
 const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;partyAttempting=true;
 try{
  if(!partyContext){partyContext=new Audio();partyContext.addEventListener('statechange',()=>{if(partyContext.state==='running')playPartySound();});}const ctx=partyContext;
  if(ctx.state!=='running'){ctx.resume().catch(()=>{});if(ctx.state!=='running')return;}
  if(box.dataset.newsId!==id||box.hidden)return;
  partyPlayed=id;try{localStorage.setItem('klippen-party-seen',id);}catch{}
  [523.25,659.25,783.99,1046.5,1318.5,1567.98,2093].forEach((freq,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type=i<4?'triangle':'sine';o.frequency.value=freq;const t=ctx.currentTime+i*.12;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.085,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.36);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+.37);});
 }catch{}finally{partyAttempting=false;}
}
const originalRenderTeamCelebration=renderTeamCelebration;
renderTeamCelebration=function(){originalRenderTeamCelebration();const box=document.querySelector('#celebration');if(!box||box.hidden)return;box.querySelector('.celebration-spark').outerHTML=partyIllustration();playPartySound();};
document.addEventListener('pointerdown',playPartySound,{passive:true});document.addEventListener('keydown',playPartySound,{passive:true});

