function renderTeamLogin(){
 const host=document.querySelector('#teamLogin');if(!host)return;const expanded=host.querySelector('details')?.open||teamPasswordSetup;const e=escapeHTML;
 host.innerHTML=`${!teamUser?'<p class="first-login-help"><strong>Første gang?</strong> Åbn invitationen i din e-mail og vælg din personlige adgangskode. Har du allerede accepteret invitationen, kan du vælge en ny kode under medarbejderlogin.</p>':''}<details class="team-login-details" ${expanded?'open':''}><summary><strong>Medarbejder${teamUser&&teamRole?' · '+e(teamUser.email):'login'}</strong><span>${teamUser&&teamRole?(teamPasswordSetup?'Vælg din adgangskode':teamRole==='manager'?'Leder':'Medarbejder'):'Log ind for at følge op'} <span aria-hidden="true">⌄</span></span></summary><div class="team-login-content"><p role="status" aria-live="polite">${e(teamStatus)}</p>${teamUser&&teamRole?`<div class="team-actions"><span>Noter og afkrydsninger deles automatisk med teamet.</span><button type="button" id="teamRefresh" title="Hent kollegernes seneste noter og afkrydsninger. Det sker også automatisk hvert 30. sekund.">Hent seneste ændringer</button><button type="button" id="teamLogout">Log ud</button></div>${teamPasswordSetup?`<form id="teamPasswordForm"><p><strong>Opret din personlige adgangskode</strong><br>Det gør du kun første gang. Brug mindst 12 tegn.</p><label>Vælg din personlige adgangskode<input name="newPassword" type="password" minlength="12" autocomplete="new-password" required></label><button type="submit">Gem adgangskode</button></form>`:''}`:teamClient?`<form id="teamLoginForm"><label>E-mail<input type="email" name="email" autocomplete="username" required></label><label>Adgangskode<input type="password" name="password" autocomplete="current-password" required></label><button type="submit">Log ind</button><button type="button" id="teamResetPassword">Første gang / glemt adgangskode?</button></form><small>Kun inviterede medarbejdere kan logge ind.</small>${teamUser?'<button type="button" id="teamLogout">Log ud</button>':''}`:'<p>Medarbejderlogin indlæses…</p>'}</div></details>`;

 host.querySelector('#teamLoginForm')?.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget,button=form.querySelector('button');button.disabled=true;const email=form.elements.email.value.trim(),password=form.elements.password.value;form.elements.password.value='';const {data,error}=await teamClient.auth.signInWithPassword({email,password});if(error){teamStatus='Login mislykkedes. Kontrollér e-mail og adgangskode.';renderTeamLogin();return;}teamUser=data.user;await refreshTeamWorkflow();});
 host.querySelector('#teamResetPassword')?.addEventListener('click',async()=>{const email=host.querySelector('[name=email]').value.trim();if(!email){alert('Skriv din e-mail først.');return;}const {error}=await teamClient.auth.resetPasswordForEmail(email,{redirectTo:'https://dashboard.hotelklippen.dk/'});teamStatus=error?'Mailen kunne ikke sendes. Kontakt Jannie.':'Hvis kontoen findes, modtager du et link til at vælge adgangskode.';renderTeamLogin();});
 host.querySelector('#teamPasswordForm')?.addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget;const password=form.elements.newPassword.value;form.elements.newPassword.value='';const {error}=await teamClient.auth.updateUser({password});if(error){teamStatus='Adgangskoden kunne ikke gemmes. Prøv igen.';}else{teamPasswordSetup=false;teamStatus='Din personlige adgangskode er gemt.';}renderTeamLogin();});
 host.querySelector('#teamRefresh')?.addEventListener('click',()=>refreshTeamWorkflow());
 host.querySelector('#teamLogout')?.addEventListener('click',async()=>{await teamClient.auth.signOut();clearTeamSession();});
}
function clearTeamSession(){teamUser=null;teamRole=null;reviewWorkflow={};workflowVersions={};privateFeedback=[];privateFeedbackStatus='Log ind for at se e-mailfeedback.';renderPrivateFeedback();teamStatus='Logget ud. Interne noter er skjult.';renderTeamLogin();renderReviewTopics();renderNightReport();renderTodayOverview();}
async function refreshTeamWorkflow(){
 if(!teamClient||!teamUser||teamLoading||teamSaving)return;teamLoading=true;
 try{
  const membership=await teamClient.from('klippen_team_members').select('role').eq('email',teamUser.email.toLowerCase()).eq('active',true).maybeSingle();
  if(membership.error)throw membership.error;if(!membership.data){teamRole=null;reviewWorkflow={};workflowVersions={};teamStatus='Din konto har ikke medarbejderadgang. Kontakt lederen.';return;}
  const {data,error}=await teamClient.from('klippen_workflow').select('*');if(error)throw error;
  teamRole=membership.data.role;reviewWorkflow={};workflowVersions={};for(const row of data){reviewWorkflow[row.key]={...row.state,updatedAt:row.updated_at,updatedBy:row.updated_by};workflowVersions[row.key]=row.version;}
  const feedback=await teamClient.from('klippen_private_feedback').select('*').order('submitted_at',{ascending:false}).limit(200);privateFeedback=feedback.error?[]:feedback.data;privateFeedbackStatus=feedback.error?'Formularforbindelsen er endnu ikke aktiveret.':'Seneste feedback hentet · '+new Date().toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'})+(feedback.data.length===200?' · viser de seneste 200':'');
  teamStatus='Fælles status opdateret · '+new Date().toLocaleTimeString('da-DK',{hour:'2-digit',minute:'2-digit'});
 }catch(error){teamStatus='Kunne ikke hente fælles status. Prøv igen. Ændringer er låst.';teamRole=null;reviewWorkflow={};workflowVersions={};}
 finally{teamLoading=false;if(!teamRole){privateFeedback=[];privateFeedbackStatus='Log ind for at se e-mailfeedback.';}renderTeamLogin();renderReviewTopics();renderNightReport();renderTodayOverview();renderPrivateFeedback();}
}
async function initializeTeamBackend(){
 renderTeamLogin();if(!teamBackendConfig.url||!teamBackendConfig.publishableKey)return;
 try{
  if(!teamBackendConfig.publishableKey.startsWith('sb_publishable_'))throw Error('En hemmelig nøgle må ikke bruges i dashboardet.');
  const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.117.3');
  teamClient=createClient(teamBackendConfig.url,teamBackendConfig.publishableKey);
  const {data,error}=await teamClient.auth.getSession();if(error)throw error;teamUser=data.session?.user||null;
  teamClient.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY')teamPasswordSetup=true;if(event==='SIGNED_OUT'){clearTeamSession();}else if(session){teamUser=session.user;setTimeout(()=>refreshTeamWorkflow(),0);}});
  if(teamUser)await refreshTeamWorkflow();else{teamStatus='Log ind for at ændre fælles status og se interne noter.';renderTeamLogin();}
  setInterval(()=>{if(!document.querySelector('[data-workflow-key]:focus'))refreshTeamWorkflow();},30000);
  window.addEventListener('focus',()=>{if(!document.querySelector('[data-workflow-key]:focus'))refreshTeamWorkflow();});
 }catch(error){teamStatus='Medarbejderlogin kunne ikke indlæses. Prøv at genindlæse siden.';renderTeamLogin();}
}
